import sys

def main():
    s = sys.stdin.readline().strip()
    ans = []

    for ch in s:
        if ch == 'A':
            cnt = 0
            while ans and ans[-1] == 'W':
                ans.pop()
                cnt += 1
            ans.append('A')
            ans.extend('C' * cnt)
        else:
            ans.append(ch)

    print(''.join(ans))

if __name__ == "__main__":
    main()
